INSERT INTO `rubrics_marks` VALUES (6,'tpl_fyp1_marking_v7','BCS23090016','Darren Eng Zi Wei','Khairunnisa Ibrahim','','Automated FYP Management and Marking Portal',NULL,NULL,'{\"title\":\"CSS3714 Final Year Project I Marking Rubric (BCS) Ver. 7\",\"course\":\"CSS3714 Final Year Project I\",\"fyp_stage\":\"FYP1\",\"student\":{\"name\":\"Darren Eng Zi Wei\",\"id\":\"BCS23090016\",\"supervisor\":\"KhairunnisaIlrahim\",\"examiner\":\"\",\"project\":\"Automated FYP Management and Marking Portal\"},\"clos\":[\"CO1: Acknowledge the continuous development of knowledge and the needs of self-upgrading.\",\"CO2: Define the objectives of a research.\",\"CO3: Compare reviews on previous research.\",\"CO4: Carry out methodology to collect data for conducting research.\",\"CO5: Prepare the schedule of a research.\",\"CO6: Produce a research proposal.\"],\"section_order\":[\"presentation\",\"project_outcome\",\"sv_evaluation\",\"report\"],\"section_meta\":{\"presentation\":{\"label\":\"Part I Presentation\",\"mark_total\":26,\"total_weight\":13,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"Supervisor (S) marks \\/100*weight + Moderator (M) marks\\/100 * weight\"},\"project_outcome\":{\"label\":\"Project Outcome\",\"mark_total\":25,\"total_weight\":12.5,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"Supervisor (S) marks \\/100*weight + Moderator (M) marks\\/100 * weight\"},\"sv_evaluation\":{\"label\":\"SV Evaluation\",\"mark_total\":24,\"total_weight\":24,\"evaluators\":[\"s\"],\"compilation\":\"\"},\"report\":{\"label\":\"Report\",\"mark_total\":25,\"total_weight\":12.5,\"evaluators\":[\"s\",\"m\"],\"compilation\":\"\"}},\"presentation\":[{\"item\":\"Overall Delivery\",\"co\":\"CO1\",\"weight\":1.5,\"levels\":[\"Presentation lack of structure, background not properly introduced, and proposed solution does not seem to be linked.\",\"Presentation organization seems adequate although linkage between background of project with proposed solution is unclear.\",\"Clear organizational pattern. Smooth presentation where background of project is explained together with acceptable solution.\",\"Professionally-structured. Very smooth presentation where background of project is explained clearly before going into very innovative solution.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Communication Skill\",\"co\":\"CO1\",\"weight\":1.5,\"levels\":[\"Poor body language, gestures, pace\\/speed, pitch, slide arrangement and\\/or enunciation.\",\"Good body language and gestures but poor on pace\\/speed, slide arrangement, pitch\\/enunciation.\",\"Good body language, gestures, pitch, slide arrangement and\\/or enunciation but not at correct pace\\/speed.\",\"Excellent body language, gestures, pace\\/speed, pitch, slide arrangement and\\/or enunciation.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Objectives Presentment\",\"co\":\"CO2\",\"weight\":2,\"levels\":[\"Does not give relevance objectives that relates to the project background, problem statements, and project scope.\",\"Able to give limited information on objectives that relates to the project background, problem statements, and project scope.\",\"Able to state the objectives but not relate to the project background, problem statements, and project scope.\",\"Able to provide and explain the objectives with regards to project background, problem statements, and project scope.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Review Justification\",\"co\":\"CO3\",\"weight\":3,\"levels\":[\"Does not give sufficient information that relates to the research topic or without proper citation.\",\"Able to give limited information on statement related to research topic using sentences directly from the sources.\",\"Able to state the problem but somewhat unable to relate the problem to research topic using own words.\",\"Able to relate problem statement to project using extensive information from various sources using own sentences in presentation.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Methodology Clarification\",\"co\":\"CO4\",\"weight\":1.5,\"levels\":[\"Unable to explain the experimental design, procedure and suitable analysis method.\",\"Able to explain experimental design procedure but unable to justify the selection of suitable analysis method.\",\"Able to elaborate design and experimental procedure but does not clearly justify the selection of analysis method.\",\"Able to elaborate design and procedures of experiment and justify the selection of suitable analysis method.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Q & A\",\"co\":\"CO4\",\"weight\":1.5,\"levels\":[\"Able to partially answer and defend project findings but unable to project background and scope.\",\"Able to answer and defend project findings and have difficulty to relate with project background and scope.\",\"Confidence in answering and defending project finding based on the understanding to project background and scope.\",\"Clearly and precisely answers and defends project findings based on understanding to project background and scope.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Project Schedule\",\"co\":\"CO5\",\"weight\":2,\"levels\":[\"Gives a Gantt chart with limited details.\",\"Gives a Gantt chart with limited information regarding work breakdown structure and visualizes tasks on a timeline.\",\"Gives and describes Gantt chart regarding work breakdown structure with sufficient scope of work, and visualizes specific tasks on a timeline.\",\"Gives and describes Gantt chart regarding work breakdown structure with the scope of work, and visualizes all tasks on a timeline, showing their start and finish dates, dependencies between them and other information.\"],\"s\":0,\"m\":0,\"comments\":\"\"}],\"project_outcome\":[{\"item\":\"Innovative Value\",\"co\":\"CO1\",\"weight\":3,\"levels\":[\"Proposed project exists abundantly or did not relate to the introduced problem.\",\"Proposed project is not new, and quite beneficial to the introduced problem.\",\"Proposed project is not new but beneficial and less applied to the introduced problem.\",\"Proposed project is very innovative, significantly beneficial and applicable to the introduced problem.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Tech Stack\\/Tools Application\",\"co\":\"CO3\",\"weight\":3,\"levels\":[\"Tech stack\\/tools chosen are not justified\\/suitable.\",\"Tech stack\\/tools chosen are adequately justified\\/suitable.\",\"Tech stack\\/tools chosen are justified\\/suitable.\",\"Tech stack\\/tools chosen are excellently justified\\/suitable.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Preliminary Implementation\",\"co\":\"CO4\",\"weight\":3,\"levels\":[\"No preliminary UI\\/experiments have been conducted.\",\"Poor preliminary UI\\/experiments have been designed\\/conducted.\",\"Sufficient preliminary UI\\/experiments have been partially designed\\/conducted.\",\"UI\\/experiments have been partially designed\\/conducted. Some preliminary results have been obtained\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"Time Management\",\"co\":\"CO5\",\"weight\":1,\"levels\":[\"End product in FYP1 shows students\' poor management of time in conducting it.\",\"End product in FYP1 shows students\' sufficient management of time in conducting it.\",\"End product in FYP1 shows students\' good management of time in conducting it.\",\"End product in FYP1 shows students\' excellent management of time in conducting it.\"],\"s\":0,\"m\":0,\"comments\":\"\"},{\"item\":\"End Product Demo\\/Delivery\",\"co\":\"CO6\",\"weight\":2.5,\"levels\":[\"No final outcome of FYP1 that has a solid existence to be delivered\\/presented, only theory\\/process idea.\",\"Final outcome of FYP1 has a slight existence to be delivered\\/presented.\",\"Final outcome of FYP1 has little existence to be delivered\\/presented.\",\"Final outcome of FYP1 has a solid existence\\/prototype to be delivered\\/presented.\"],\"s\":0,\"m\":0,\"comments\":\"\"}],\"justification\":\"\",\"general_comments\":\